-- BizStack provider-neutral wallet operations layer.
create table if not exists public.wallets (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,name text not null,wallet_type text not null default 'operating' check (wallet_type in ('operating','reserve','tax','payroll','savings','escrow','merchant','virtual')),currency text not null,status text not null default 'active' check (status in ('active','locked','suspended','closed')),available_balance numeric not null default 0,pending_balance numeric not null default 0,ledger_balance numeric not null default 0,provider text,provider_wallet_id text,is_default boolean not null default false,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(business_id,name,currency));
create table if not exists public.wallet_transactions (id uuid primary key default gen_random_uuid(),wallet_id uuid not null references public.wallets(id) on delete cascade,business_id uuid not null references public.businesses(id) on delete cascade,type text not null check(type in ('deposit','withdrawal','transfer_in','transfer_out','payment','refund','fee','adjustment','fx_conversion','reserve_hold','reserve_release','cash_deposit','cash_withdrawal')),direction text not null check(direction in ('credit','debit')),status text not null default 'pending' check(status in ('pending','processing','completed','failed','cancelled','reversed','requires_approval')),amount numeric not null check(amount>0),fee_amount numeric not null default 0,net_amount numeric not null,currency text not null,counterparty_name text,counterparty_reference text,description text,external_reference text,provider text,provider_transaction_id text,idempotency_key text,parent_transaction_id uuid references public.wallet_transactions(id) on delete set null,scheduled_for timestamptz,completed_at timestamptz,metadata jsonb not null default '{}'::jsonb,created_by uuid,created_at timestamptz not null default now(),unique(business_id,idempotency_key));
create table if not exists public.wallet_beneficiaries (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,display_name text not null,destination_type text not null check(destination_type in ('bank_account','wallet','mobile_money','card','cash','internal')),provider text,provider_recipient_id text,account_name text,masked_account text,bank_name text,country text,currency text,status text not null default 'pending_verification' check(status in ('pending_verification','verified','blocked')),metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.wallet_transfer_requests (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,source_wallet_id uuid not null references public.wallets(id),beneficiary_id uuid references public.wallet_beneficiaries(id),destination_wallet_id uuid references public.wallets(id),amount numeric not null check(amount>0),currency text not null,fee_estimate numeric not null default 0,status text not null default 'draft' check(status in ('draft','awaiting_approval','queued','processing','completed','failed','cancelled','reversed')),scheduled_for timestamptz,provider text,external_reference text,idempotency_key text not null unique,approval_required boolean not null default false,approved_by uuid,approved_at timestamptz,failure_reason text,metadata jsonb not null default '{}'::jsonb,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.wallet_funding_requests (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,wallet_id uuid not null references public.wallets(id),direction text not null check(direction in ('deposit','withdrawal')),method text not null check(method in ('bank_transfer','card','mobile_money','cash','payment_processor','internal_transfer')),amount numeric not null check(amount>0),currency text not null,status text not null default 'pending' check(status in ('pending','processing','completed','failed','cancelled','requires_action')),provider text,provider_reference text,fee_amount numeric not null default 0,idempotency_key text not null unique,failure_reason text,metadata jsonb not null default '{}'::jsonb,created_by uuid,created_at timestamptz not null default now(),completed_at timestamptz);
create table if not exists public.wallet_limits (id uuid primary key default gen_random_uuid(),business_id uuid not null unique references public.businesses(id) on delete cascade,daily_send_limit numeric,single_transfer_limit numeric,daily_withdrawal_limit numeric,approval_threshold numeric,require_approval_above_threshold boolean not null default true,require_2fa_for_sensitive_actions boolean not null default true,updated_at timestamptz not null default now());
create table if not exists public.wallet_security_events (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,wallet_id uuid references public.wallets(id) on delete set null,event_type text not null,severity text not null default 'info' check(severity in ('info','warning','critical')),description text not null,ip_hash text,user_agent_hash text,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create table if not exists public.wallet_recurring_rules (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,source_wallet_id uuid not null references public.wallets(id),beneficiary_id uuid references public.wallet_beneficiaries(id),amount numeric not null check(amount>0),currency text not null,frequency text not null check(frequency in ('daily','weekly','monthly','quarterly','yearly')),next_run_at timestamptz not null,end_at timestamptz,status text not null default 'active' check(status in ('active','paused','cancelled')),purpose text,created_by uuid,created_at timestamptz not null default now());
create table if not exists public.wallet_disputes (id uuid primary key default gen_random_uuid(),business_id uuid not null references public.businesses(id) on delete cascade,wallet_transaction_id uuid references public.wallet_transactions(id) on delete set null,reason text not null,amount numeric not null check(amount>0),currency text not null,status text not null default 'open' check(status in ('open','submitted','under_review','won','lost','cancelled')),provider_case_id text,evidence jsonb not null default '[]'::jsonb,created_by uuid,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
alter table public.wallets enable row level security; alter table public.wallet_transactions enable row level security; alter table public.wallet_beneficiaries enable row level security; alter table public.wallet_transfer_requests enable row level security; alter table public.wallet_funding_requests enable row level security; alter table public.wallet_limits enable row level security; alter table public.wallet_security_events enable row level security; alter table public.wallet_recurring_rules enable row level security; alter table public.wallet_disputes enable row level security;
grant select,insert,update,delete on public.wallets,public.wallet_transactions,public.wallet_beneficiaries,public.wallet_transfer_requests,public.wallet_funding_requests,public.wallet_limits,public.wallet_security_events,public.wallet_recurring_rules,public.wallet_disputes to authenticated;
create policy wallet_owner_all on public.wallets for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallets.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallets.business_id and b.owner_id=(select auth.uid())));
create policy wallet_transactions_owner_all on public.wallet_transactions for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_transactions.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_transactions.business_id and b.owner_id=(select auth.uid())));
create policy wallet_beneficiaries_owner_all on public.wallet_beneficiaries for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_beneficiaries.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_beneficiaries.business_id and b.owner_id=(select auth.uid())));
create policy wallet_transfer_requests_owner_all on public.wallet_transfer_requests for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_transfer_requests.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_transfer_requests.business_id and b.owner_id=(select auth.uid())));
create policy wallet_funding_requests_owner_all on public.wallet_funding_requests for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_funding_requests.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_funding_requests.business_id and b.owner_id=(select auth.uid())));
create policy wallet_limits_owner_all on public.wallet_limits for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_limits.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_limits.business_id and b.owner_id=(select auth.uid())));
create policy wallet_security_events_owner_all on public.wallet_security_events for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_security_events.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_security_events.business_id and b.owner_id=(select auth.uid())));
create policy wallet_recurring_rules_owner_all on public.wallet_recurring_rules for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_recurring_rules.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_recurring_rules.business_id and b.owner_id=(select auth.uid())));
create policy wallet_disputes_owner_all on public.wallet_disputes for all to authenticated using(exists(select 1 from public.businesses b where b.id=wallet_disputes.business_id and b.owner_id=(select auth.uid()))) with check(exists(select 1 from public.businesses b where b.id=wallet_disputes.business_id and b.owner_id=(select auth.uid())));
insert into public.wallet_limits(business_id) select id from public.businesses on conflict (business_id) do nothing;